// Simulating a simplified NAT lookup table mapping
class NATRouter {
  constructor(publicIP) {
    this.publicIP = publicIP;
    this.translationTable = new Map();
  }

  outbound(privateIP, privatePort, destIP, destPort) {
    const natPort = Math.floor(Math.random() * 10000) + 40000;
    this.translationTable.set(natPort, { privateIP, privatePort });
    // Router rewrites source IP to public IP and source port to natPort
    return { srcIP: this.publicIP, srcPort: natPort, destIP, destPort };
  }

  inbound(natPort, destIP, destPort) {
    const original = this.translationTable.get(natPort);
    return original ? original : null;
  }
}

