// Simulating the DORA lease state machine in JavaScript
class DHCPClient {
  constructor(macAddress) {
    this.macAddress = macAddress;
    this.state = 'INIT';
    this.ipAddress = null;
  }

  discover() {
    this.state = 'SELECTING';
    console.log(`[${this.macAddress}] Sent DHCPDISCOVER`);
    return { type: 'DHCPDISCOVER', mac: this.macAddress };
  }

  request(offer) {
    this.ipAddress = offer.ip;
    this.state = 'REQUESTING';
    console.log(`[${this.macAddress}] Sent DHCPREQUEST for ${this.ipAddress}`);
    return { type: 'DHCPREQUEST', ip: this.ipAddress };
  }

  acknowledge(ack) {
    if (ack.success) {
      this.state = 'BOUND';
      console.log(`[${this.macAddress}] Lease acquired! IP: ${this.ipAddress}`);
    }
  }
}
