const crypto = require('crypto');

const content = "Hello Gurugram University AI Students!";
const etag = crypto.createHash('md5').update(content).digest('hex');

const server = http.createServer((req, res) => {
  const clientETag = req.headers['if-none-match'];

  if (clientETag === etag) {
    // Resource hasn't changed, send 304 with no body
    res.writeHead(304);
    res.end();
  } else {
    // Send fresh content with caching headers
    res.writeHead(200, {
      'Content-Type': 'text/plain',
      'Cache-Control': 'public, max-age=60',
      'ETag': etag
    });
    res.end(content);
  }
});

