// Node.js Express example for handling filtering and sorting
const express = require('express');
const app = express();

const items = [
  { id: 1, name: 'Apple', price: 10, category: 'fruit' },
  { id: 2, name: 'Banana', price: 5, category: 'fruit' },
  { id: 3, name: 'Carrot', price: 8, category: 'veg' }
];

app.get('/api/items', (req, res) => {
  let { category, sort, search } = req.query;
  let results = [...items];

  // 1. Filtering
  if (category) {
    results = results.filter(item => item.category === category);
  }

  // 2. Searching
  if (search) {
    results = results.filter(item => item.name.toLowerCase().includes(search.toLowerCase()));
  }

  // 3. Sorting (e.g., sort=price or sort=-price)
  if (sort) {
    const isDesc = sort.startsWith('-');
    const field = isDesc ? sort.substring(1) : sort;
    results.sort((a, b) => {
      if (a[field] < b[field]) return isDesc ? 1 : -1;
      if (a[field] > b[field]) return isDesc ? -1 : 1;
      return 0;
    });
  }

  res.json({ count: results.length, data: results });
});

