// Node.js Express simple Fixed Window Rate Limiter using a Map
const express = require('express');
const app = express();

const WINDOW_SIZE_IN_MS = 60 * 1000; // 1 minute
const MAX_REQUESTS = 3;
const requestsStore = new Map();

app.use((req, res, next) => {
  const ip = req.ip;
  const currentTime = Date.now();

  if (!requestsStore.has(ip)) {
    requestsStore.set(ip, { count: 1, startTime: currentTime });
    return next();
  }

  let clientData = requestsStore.get(ip);

  // Check if window has expired
  if (currentTime - clientData.startTime > WINDOW_SIZE_IN_MS) {
    clientData.count = 1;
    clientData.startTime = currentTime;
    return next();
  }

  if (clientData.count < MAX_REQUESTS) {
    clientData.count++;
    return next();
  }

  // Limit exceeded
  res.setHeader('Retry-After', Math.ceil((WINDOW_SIZE_IN_MS - (currentTime - clientData.startTime)) / 1000));
