// Simple Round-Robin Load Balancer implementation in Node.js
const http = require('http');

const servers = [
  { host: 'localhost', port: 5001 },
  { host: 'localhost', port: 5002 }
];

let current = 0;

// Simple Load Balancer Server
const lbServer = http.createServer((clientReq, clientRes) => {
  const target = servers[current];
  current = (current + 1) % servers.length; // Round Robin index rotation

  const options = {
    hostname: target.host,
    port: target.port,
    path: clientReq.url,
    method: clientReq.method,
    headers: clientReq.headers
  };

  const proxyReq = http.request(options, (targetRes) => {
    clientRes.writeHead(targetRes.statusCode, targetRes.headers);
    targetRes.pipe(clientRes, { end: true });
  });

  clientReq.pipe(proxyReq, { end: true });
});

lbServer.listen(8000, () => {
  console.log('Load Balancer running on port 8000 using Round Robin');
});

