// Simulating a CDN caching layer lookup for static assets in Node.js
const http = require('http');

const cdnCache = new Map(); // Simulated Edge Cache
const originServerUrl = 'http://origin.mycompany.com';

const server = http.createServer(async (req, res) => {
  const assetKey = req.url;

  // Check Edge Cache (Cache Hit/Miss)
  if (cdnCache.has(assetKey)) {
    console.log(`[CDN Edge] Cache HIT for ${assetKey}`);
    res.writeHead(200, { 'X-Cache': 'HIT', 'Content-Type': 'text/plain' });
    res.end(cdnCache.get(assetKey));
    return;
  }

  console.log(`[CDN Edge] Cache MISS for ${assetKey}. Fetching from origin...`);

  // Simulated fetch from origin server
  const fetchedData = `Data content for ${assetKey} fetched from Origin`;
  cdnCache.set(assetKey, fetchedData); // Cache at edge

  res.writeHead(200, { 'X-Cache': 'MISS', 'Content-Type': 'text/plain' });
  res.end(fetchedData);
});

server.listen(3000, () => console.log('CDN Edge Node running on port 3000'));

// Basic API Gateway routing and rate limiting middleware using Node.js & Express
const express = require('express');
