// Simulating a Cache-Aside (Lazy Loading) pattern with an in-memory Map representing Redis
class InMemoryRedis {
  constructor() { this.store = new Map(); }
  async get(key) { return this.store.get(key) || null; }
  async set(key, val) { this.store.set(key, val); }
}

const redis = new InMemoryRedis();

async function getUserData(userId) {
  const cacheKey = `user:${userId}`;

  // 1. Check Cache
  const cached = await redis.get(cacheKey);
  if (cached) {
    console.log('[Cache] HIT');
    return JSON.parse(cached);
  }

  console.log('[Cache] MISS. Querying Database...');
  // 2. Simulate Database Fetch
  const dbData = { id: userId, name: 'Priya Sharma', college: 'Gurugram University' };

  // 3. Store in Cache for next time
  await redis.set(cacheKey, JSON.stringify(dbData));
  return dbData;
}

